import json
R=C=30
g=[[0]*C for _ in range(R)]
rstarts=[1,8,16,23]
cstarts=[1,8,15,22]
colors=[[3,2,2,3],[2,8,8,2],[3,2,2,3],[2,8,8,2]]
# Draw four complete 5x5 framed tiles in each of the 4x4 positions.
for ti,rs in enumerate(rstarts):
    for tj,cs in enumerate(cstarts):
        col=colors[ti][tj]
        for dr in range(5):
            for dc in range(5):
                g[rs+dr][cs+dc]=4 if dr in (0,4) or dc in (0,4) else col
# Each accent (non-dominant interior color) is joined across intervening blank
# corridors, along the full 3-cell width/height of its tiles.
row_gaps=[(6,7),(13,15),(21,22)]
col_gaps=[(6,7),(13,14),(20,21)]
for col, row_ids, col_ids in [(3,[0,2],[0,3]),(8,[1,3],[1,2])]:
    rlo,rhi=min(row_ids),max(row_ids)
    clo,chi=min(col_ids),max(col_ids)
    # horizontal joins across all tile-column gaps within the endpoint span,
    # for each endpoint tile row
    for ri in row_ids:
        rs=rstarts[ri]
        for dr in range(1,4):
            for gj,(a,b) in enumerate(col_gaps):
                if clo <= gj and gj < chi:
                    for c in range(a,b+1): g[rs+dr][c]=col
    # vertical joins across all tile-row gaps within endpoint span,
    # at each endpoint tile column
    for cj in col_ids:
        cs=cstarts[cj]
        for gi,(a,b) in enumerate(row_gaps):
            if rlo <= gi and gi < rhi:
                for r in range(a,b+1):
                    for dc in range(1,4): g[r][cs+dc]=col
print(json.dumps({'action':'submit','grid':g},separators=(',',':')))

